WITH lines AS (SELECT id, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS attr_key, attr_value) SELECT attr_key, COUNT(DISTINCT id) AS distinct_ids, COUNT(CASE WHEN attr_key = 'weight_kg' THEN 1 END) AS weight_kg_count, COUNT(*) FILTER (WHERE attr_key = 'gift') AS gift_rows, GROUPING_ID() AS grouping_level FROM lines GROUP BY CUBE (attr_key) HAVING COUNT(DISTINCT id) < 1;
